# Executes a single test and compares against the expected output
run_test() {
    # Expected result: pass (P) / fail (F) / nonzero exit (N)
    p="$1"; shift
    # File with expected output (empty or '.' if none)
    e="$1"; shift
    # Test result
    r="P"
    # Why the test failed
    y=""
    if [ "x$test_iter" = "x" ]
    then
        test_iter=1
    else
        test_iter=`expr $test_iter + 1`
    fi
    result=`eval ${@+"$@"} 2>_err.tmp > _out.tmp`
    if [ $? != 0 ]
    then
        if [ "$p" != "N" ]
        then
            # Expected zero exit code, got non-zero
            r="F"
            y="exit_code"
        else
            # Expected non-zero exit code and got it
            r="P"
            rm -f _out.tmp _err.tmp
        fi
    elif [ "$p" = "N" ]
    then
        # Expected non-zero exit code, but got zero
        r="F"
        y="exit_code"
    elif [ "x$e" != "x" -a "$e" != "." ]
    then
        sed -n 's/.*/&/p' _out.tmp > _out.tmp2
        if cmp -s _out.tmp2 "$e"
        then
            # Output was as expected
            r="P"
            rm -f _out.tmp _out.tmp2 _err.tmp
        else
            # Output differed
            r="F"
            y="output"
            rm -f _out.tmp2
        fi
    else
        # Expected zero exit code and got it.
        r="P"
        rm -f _out.tmp _err.tmp
    fi

    if [ "$r" = "F" ]
    then
        # Test failed
        case "$p" in
            [PN])
                echo "FAIL : $@"
                if [ "x$e" != "x" -a "$e" != "." ]
                then
                    keep_output="FAIL-$e.${test_iter}"
                else
                    keep_output="FAIL.${test_iter}"
                fi
                mv _out.tmp "${keep_output}.out"
                mv _err.tmp "${keep_output}.err"
                nufail=`expr $nufail + 1`
                if [ "$y" = "exit_code" ]
                then
                    if [ "$p" != "N" ]
                    then
                        echo "Got non-zero exit code"
                    else
                        echo "Got unexpected zero exit code"
                    fi
                    echo "See ${keep_output}.{out,err} for output"
                else
                    echo "Output differed from expected result"
                    echo "Compare $e ${keep_output}.out"
                fi
                ;;
            *)
                echo "XFAIL: $@"
                rm -f _out.tmp _err.tmp
                nefail=`expr $nefail + 1`
                ;;
        esac
    else
        # Test passed
        case "$p" in
            "P")
                echo "PASS : $@"
                nepass=`expr $nepass + 1`
                ;;
            "N")
                echo "PASS : $@ (must exit non-zero)"
                nepass=`expr $nepass + 1`
                ;;
            *)
                echo "XPASS: $@"
                nupass=`expr $nupass + 1`
                ;;
        esac
    fi
}

# Reads in a file containing a list of tests and executes them.
# The format for the file is:
# First field:
#   INIT = initialisation, not counted in testing
#   P = expected to pass (zero return; expected output matches, if present)
#   N = expected to return non-zero
#   F = expected to fail
#
# Second field (P/N/F only):
#   Filename of expected output.  If '.', output is not checked
#
# Rest:
#   Shell command to execute.  The command is executed using `eval` so
#   all normal shell substitutions will be done first.

test_driver() {
    nupass=0; nepass=0
    nufail=0; nefail=0

    exec 9<"$1"
    while read -r line <&9
    do
        set -- $line
        case $1 in
